        DB::transaction(function () use ($data) {
            foreach ($data as $row) {
                $kecamatan = Kecamatan::where('nama', $row['kecamatan'])->first();
                if (!$kecamatan) {
                    throw new \RuntimeException("Kecamatan tidak ditemukan: {$row['kecamatan']}");
                }

                $kelurahan = Kelurahan::where('nama', $row['kelurahan'])
                    ->where('kecamatan_id', $kecamatan->id)
                    ->first();

                if (!$kelurahan) {
                    throw new \RuntimeException(
                        "Kelurahan tidak ditemukan: {$row['kelurahan']} ({$row['kecamatan']})"
                    );
                }

                $regu = Regu::firstOrCreate(
                    ['nama' => $row['regu']],
                    ['aktif' => true]
                );

                KejadianKebakaran::updateOrCreate(
                    ['id_kejadian' => $row['id_kejadian']],
                    [
                        'kecamatan_id' => $kecamatan->id,
                        'kelurahan_id' => $kelurahan->id,
                        'alamat_lengkap' => $row['alamat_lengkap'],
                        'nama_pemilik' => $row['nama_pemilik'],
                        'tanggal' => $row['tanggal'],
                        'waktu_kejadian' => $row['waktu_kejadian'],
                        'waktu_tiba' => $row['waktu_tiba'],
                        'waktu_selesai' => $row['waktu_selesai'],
                        'durasi_menit' => $row['durasi_menit'],
