                        'korban_jiwa' => $row['korban_jiwa'],
                        'jumlah_unit' => $row['jumlah_unit'],
                        'regu_id' => $regu->id,
                        'keterangan_korban' => $row['keterangan_korban'],
                    ]
                );
            }
